class Solution {
public:
    int vowelConsonantScore(string s) {
        int v=0,c=0;
        for(char ch:s){
            ch=tolower((unsigned char)ch);
            if(ch<'a'||ch>'z') continue;
            if(string("aeiou").find(ch)!=string::npos) ++v;
            else ++c;
        }
        return c==0?0:v/c;
    }
};
